  "tarifas26.kicker":      { es: "Aviso importante", en: "Important notice", zh: "重要通知", ru: "Важное уведомление" },
  "tarifas26.title":       { es: "Nuevas tarifas del aéreo desde el 25/09", en: "New air freight rates from Sep 25", zh: "9月25日起空运新费率", ru: "Новые тарифы на авиадоставку с 25.09" },
  "tarifas26.intro":       { es: "Las aerolíneas aplicaron nuevos recargos por combustible y estamos entrando en temporada alta, cuando el espacio en bodega es más caro. Por eso, desde el viernes 25 de septiembre rigen nuevas tarifas para la carga aérea vía Courier Comercial.", en: "Airlines have applied new fuel surcharges and we are entering peak season, when cargo space is more expensive. Therefore, from Friday, September 25 new rates apply to air freight via Commercial Courier.", zh: "航空公司加收了新的燃油附加费，且正进入旺季，舱位更贵。因此自9月25日（星期五）起，商业快递空运执行新费率。", ru: "Авиакомпании ввели новые топливные сборы, и начинается высокий сезон, когда место в грузовом отсеке дороже. Поэтому с пятницы, 25 сентября, действуют новые тарифы на авиадоставку через коммерческий курьер." },
  "tarifas26.tier1":       { es: "De 10 a 25 kg", en: "10 to 25 kg", zh: "10至25公斤", ru: "От 10 до 25 кг" },
  "tarifas26.tier2ri":     { es: "Más de 25 kg", en: "Over 25 kg", zh: "25公斤以上", ru: "Свыше 25 кг" },
  "tarifas26.tier2":       { es: "De 25 a 100 kg", en: "25 to 100 kg", zh: "25至100公斤", ru: "От 25 до 100 кг" },
  "tarifas26.tier3":       { es: "Más de 100 kg", en: "Over 100 kg", zh: "100公斤以上", ru: "Свыше 100 кг" },
  "tarifas26.min":         { es: "El mínimo facturable pasa a 10 kg.", en: "The minimum billable weight is now 10 kg.", zh: "最低计费重量调整为10公斤。", ru: "Минимальный оплачиваемый вес — 10 кг." },
  "tarifas26.batt":        { es: "Productos con baterías: + USD 1 por kg.", en: "Products with batteries: + USD 1 per kg.", zh: "含电池产品：每公斤加收1美元。", ru: "Товары с батареями: + 1 USD за кг." },
  "tarifas26.keep":        { es: "Tus operaciones abiertas y en tránsito mantienen la tarifa anterior.", en: "Your open and in-transit operations keep the previous rate.", zh: "您已开立和运输中的业务保持原费率。", ru: "Для открытых операций и грузов в пути сохраняется прежний тариф." },
  "tarifas26.desad":      { es: "Gasto documental de aduana: USD 65 + IVA para CIF hasta USD 100.", en: "Customs documentation fee: USD 65 + VAT for CIF up to USD 100.", zh: "海关文件费：CIF不超过100美元的，收取65美元+增值税。", ru: "Таможенный документальный сбор: 65 USD + НДС при CIF до 100 USD." },
