  "merc.battLate": { es: "Si la carga lleva baterías (celulares, herramientas a batería, parlantes, vapes), marcalo: le avisamos a Argencargo al instante.", en: "If your cargo contains batteries (phones, cordless tools, speakers, vapes), flag it: we notify Argencargo right away.", zh: "如果您的货物含有电池（手机、无线工具、音箱、电子烟），请勾选：我们会立即通知 Argencargo。", ru: "Если в грузе есть батареи (телефоны, аккумуляторный инструмент, колонки, вейпы), отметьте это: мы сразу сообщим Argencargo." },
  "merc.battSavedOk": { es: "Listo, Argencargo ya está avisado.", en: "Done, Argencargo has been notified.", zh: "已完成，已通知 Argencargo。", ru: "Готово, Argencargo уведомлён." },
