  "merc.confirmedOk": { es: "Mercadería confirmada. Argencargo ya puede presupuestar y armar el vuelo.", en: "Goods confirmed. Argencargo can now quote and arrange the flight.", zh: "商品已确认。Argencargo 现在可以报价并安排航班。", ru: "Товар подтверждён. Argencargo может составить смету и оформить рейс." },
  "merc.readInvoice": { es: "📄 Leer la factura", en: "📄 Read the invoice", zh: "📄 读取发票", ru: "📄 Прочитать инвойс" },
  "merc.readInvoiceSub": { es: "PDF, foto o imagen pegada: detectamos los productos", en: "PDF, photo or pasted image: we detect the products", zh: "PDF、照片或粘贴的图片：我们识别产品", ru: "PDF, фото или вставленное изображение: распознаём товары" },
  "merc.manualSub": { es: "Producto por producto, como en la calculadora", en: "Product by product, like in the calculator", zh: "逐个产品录入，与计算器一样", ru: "Товар за товаром, как в калькуляторе" },
  "merc.hsHint": { es: "Si tenés la posición arancelaria que te pasó el proveedor, cargala: Argencargo la valida", en: "If you have the tariff code your supplier gave you, enter it: Argencargo will validate it", zh: "如果供应商提供了税则号，请录入：Argencargo 会进行核验", ru: "Если поставщик дал вам код ТН ВЭД, введите его: Argencargo проверит" },
