  "op.costByPkg": { es: "Cada producto carga sus impuestos según su NCM; el flete y los gastos se reparten según el bulto en que viaja.", en: "Each product carries its own duties per HS code; freight and fees are split by the package it travels in.", zh: "每件产品按其编码承担税费；运费和费用按所在包裹分摊。", ru: "Каждый товар несёт свои налоги по коду ТН ВЭД; перевозка и расходы распределяются по месту, в котором он едет." },
  "op.costByFob": { es: "Cada producto carga sus impuestos según su NCM; el flete y los gastos se reparten según el valor FOB. Si en la solapa Bultos marcás qué viaja en cada uno, el reparto sale por bulto.", en: "Each product carries its own duties per HS code; freight and fees are split by FOB value. If you mark what travels in each package on the Packages tab, the split gets more accurate.", zh: "每件产品按其编码承担税费；运费和费用按 FOB 价值分摊。如果在「包裹」标签中标记每个包裹的内容，分摊会更准确。", ru: "Каждый товар несёт свои налоги по коду ТН ВЭД; перевозка и расходы распределяются по стоимости FOB. Если на вкладке «Места» отметить, что едет в каждом месте, распределение станет точнее." },
  "op.costEstNote": { es: "Es estimado hasta que Argencargo confirme el presupuesto.", en: "It's an estimate until Argencargo confirms the quote.", zh: "在 Argencargo 确认报价前为预估值。", ru: "Это оценка, пока Argencargo не подтвердит смету." },
  "op.loadToSeeCost": { es: "Cargá la mercadería para ver el costo de cada producto.", en: "Load the goods to see each product's cost.", zh: "录入商品以查看每件产品的成本。", ru: "Загрузите товар, чтобы увидеть себестоимость каждой позиции." },
  "op.cantCalcCost": { es: "Todavía no se puede calcular el costo por producto.", en: "Cost per product can't be calculated yet.", zh: "暂时无法计算每件产品的成本。", ru: "Себестоимость по товарам пока рассчитать нельзя." },
