  "opq.loadTitle": { es: "Cargá la mercadería de tu importación", en: "Load the goods for your import", zh: "录入本次进口的商品", ru: "Загрузите товар для вашей поставки" },
  "opq.loadDesc": { es: "Leé la factura o cargala a mano, clasificá el NCM y vas a ver el costo estimado al instante.", en: "Read the invoice or enter it manually, classify the HS code and you'll see the estimated cost instantly.", zh: "读取发票或手动录入，归类编码后即可立即查看预计成本。", ru: "Считайте инвойс или введите вручную, определите код ТН ВЭД — и сразу увидите ориентировочную стоимость." },
  "opq.confirmTitle": { es: "Confirmá tu mercadería cuando esté completa", en: "Confirm your goods once the list is complete", zh: "商品录入完成后请确认", ru: "Подтвердите товар, когда список будет полным" },
  "opq.confirmDesc": { es: "Revisá los productos y tocá el botón de abajo. Después de confirmar ya no se puede editar: Argencargo presupuesta y arma el vuelo con eso.", en: "Review the products and tap the button below. After confirming you can no longer edit: Argencargo quotes and arranges the flight with that.", zh: "请检查产品并点击下方按钮。确认后将无法修改：Argencargo 会据此报价并安排航班。", ru: "Проверьте товары и нажмите кнопку ниже. После подтверждения изменить нельзя: Argencargo составит смету и оформит рейс по этим данным." },
  "opq.quotingTitle": { es: "Estamos presupuestando tu carga", en: "We're preparing your quote", zh: "我们正在为您的货物报价", ru: "Готовим смету по вашему грузу" },
  "opq.quotingDesc": { es: "Tu mercadería está confirmada. Cuando el presupuesto esté listo te avisamos; mientras tanto, abajo tenés el costo estimado y el costo de cada producto.", en: "Your goods are confirmed. We'll let you know when the quote is ready; meanwhile, below you have the estimated cost and the cost of each product.", zh: "您的商品已确认。报价准备好后我们会通知您；同时您可以在下方查看预计成本和每件产品的成本。", ru: "Ваш товар подтверждён. Сообщим, когда смета будет готова; а ниже уже есть ориентировочная стоимость и себестоимость каждой позиции." },
  "opq.payDesc": { es: "Podés pagarlo por transferencia o en efectivo. Si ya lo pagaste, mandanos el comprobante por WhatsApp.", en: "You can pay by transfer or cash. If you already paid, send us the receipt on WhatsApp.", zh: "可通过转账或现金支付。如已付款，请通过 WhatsApp 发送凭证。", ru: "Можно оплатить переводом или наличными. Если уже оплатили, пришлите подтверждение в WhatsApp." },
  "opq.balanceDue": { es: "Saldo a abonar", en: "Balance due", zh: "应付余额", ru: "К оплате" },
  "opq.readyTitle": { es: "Tu carga está lista para retirar", en: "Your shipment is ready for pickup", zh: "您的货物已可提货", ru: "Ваш груз готов к выдаче" },
  "opq.readyDesc": { es: "Te mandamos por WhatsApp el link para coordinar el retiro o el envío.", en: "We sent you the link on WhatsApp to arrange pickup or delivery.", zh: "我们已通过 WhatsApp 向您发送提货或配送安排链接。", ru: "Мы отправили вам в WhatsApp ссылку для согласования выдачи или доставки." },
  "opq.transitTitle": { es: "Tu carga está en camino", en: "Your shipment is on its way", zh: "您的货物正在运输中", ru: "Ваш груз в пути" },
  "opq.transitDesc": { es: "Te avisamos cuando llegue a Argentina.", en: "We'll let you know when it arrives in Argentina.", zh: "到达阿根廷后我们会通知您。", ru: "Сообщим, когда груз прибудет в Аргентину." },
  "opq.eta": { es: "Llegada estimada", en: "Estimated arrival", zh: "预计到达", ru: "Ожидаемое прибытие" },
  "opq.customsTitle": { es: "Tu carga está en Argentina, en gestión aduanera", en: "Your shipment is in Argentina, in customs clearance", zh: "您的货物已到阿根廷，正在清关", ru: "Ваш груз в Аргентине, проходит таможенное оформление" },
  "opq.customsDesc": { es: "Cuando esté liberada te avisamos para coordinar el retiro.", en: "We'll let you know once it's released so we can arrange pickup.", zh: "放行后我们会通知您安排提货。", ru: "Когда груз выпустят, сообщим для согласования выдачи." },
