  "calc.noWeightDims": { es: "No cargaste el peso ni las medidas de los bultos.", en: "You haven't entered the weight or dimensions of the packages.", zh: "您尚未录入包裹的重量或尺寸。", ru: "Вы не указали вес и габариты мест." },
  "calc.courierMax50": { es: "El régimen courier establece un máximo de 50 kg por bulto.", en: "The courier regime sets a maximum of 50 kg per package.", zh: "快件制度规定每件最多 50 公斤。", ru: "Курьерский режим допускает максимум 50 кг на место." },
  "calc.courierSplit": { es: "Para avanzar vía Courier comercial, dividí la carga en bultos cuyo peso unitario no supere los 50 kg.", en: "To proceed via commercial courier, split the shipment into packages of no more than 50 kg each.", zh: "如需通过商业快件发货，请将货物拆分为每件不超过 50 公斤。", ru: "Чтобы отправить коммерческим курьером, разделите груз на места не более 50 кг каждое." },
  "calc.noDimsSea": { es: "No colocaste las dimensiones de los bultos: sin volumen (m³) no se puede cotizar el marítimo.", en: "You didn't enter the package dimensions: without volume (m³) we can't quote sea freight.", zh: "您未录入包裹尺寸：没有体积（立方米）无法报海运价。", ru: "Вы не указали габариты мест: без объёма (м³) морскую перевозку рассчитать нельзя." },
